{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Ampicillin, a zwitterionic amino acid beta-lactam with multiple ionizable groups, has an absolute oral bioavailability of 40% in humans, demonstrating that highly polar/ionized molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Imipramine-N-oxide, a zwitterionic N-oxide with charged groups, showed approximately 100% systemic availability after oral dosing in healthy volunteers, indicating that polar/ionized structures are not inherently low-bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Maraviroc, a drug with transporter and first-pass metabolism liabilities, still achieves 23% systemic availability at a 100 mg oral dose, supporting that moderate oral bioavailability above 20% is achievable even with absorption barriers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability at or above 20%, including the zwitterionic amino acid ampicillin (40%), the polar N-oxide imipramine-N-oxide (~100%), and maraviroc (23-33%). The unfavorable physicochemical prior is overridden by these direct, high-transfer experimental measurements.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data exist for the exact query molecule.",
    "No analogue shares the exact combination of a free primary amine, secondary amine, and two carboxylates.",
    "The extent to which the query might be absorbed via active transporters such as PEPT1 is inferred but not directly demonstrated.",
    "The query's extremely low logD (-8.18) may be more extreme than the closest zwitterionic analogue ampicillin."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C48"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "zwitterionic amino acid beta-lactam"
    }
  ],
  "revision_action": "initial"
}

